import pickle
import json
from pathlib import Path
from fastapi import FastAPI
from pydantic import BaseModel

app = FastAPI()

model = None
model_name = None
model_type = None

class PredictInput(BaseModel):
    features: list[float]

class PredictBatchInput(BaseModel):
    features_list: list[list[float]]

@app.on_event("startup")
async def startup_event():
    global model, model_name, model_type
    with open("/app/models/best_model.pkl", "rb") as f:
        model = pickle.load(f)
    with open("/app/output/model_comparison.json", "r") as f:
        comp = json.load(f)
    model_name = comp["best_model_name"]
    # Determine model type
    if model_name == "linear_regression":
        model_type = "LinearRegression"
    elif model_name == "ridge":
        model_type = "Ridge"
    elif model_name == "random_forest":
        model_type = "RandomForestRegressor"
    else:
        model_type = type(model).__name__

@app.post("/predict")
async def predict(input_data: PredictInput):
    import numpy as np
    features = np.array(input_data.features).reshape(1, -1)
    pred = model.predict(features)[0]
    return {"prediction": float(pred), "model_name": model_name}

@app.get("/health")
async def health():
    return {"status": "healthy", "model_loaded": model is not None}

@app.get("/model-info")
async def model_info():
    return {"model_name": model_name, "model_type": model_type, "features_count": 8}

@app.post("/predict-batch")
async def predict_batch(input_data: PredictBatchInput):
    import numpy as np
    features = np.array(input_data.features_list)
    preds = model.predict(features)
    return {"predictions": [float(p) for p in preds], "model_name": model_name, "count": len(preds)}
